CREATE TYPE "Role" AS ENUM ('ADMIN','TECHNICIAN','EMPLOYEE');
CREATE TYPE "AssetStatus" AS ENUM ('AVAILABLE','ASSIGNED','MAINTENANCE','RETIRED');
CREATE TYPE "TicketStatus" AS ENUM ('OPEN','IN_PROGRESS','WAITING','RESOLVED','CLOSED');
CREATE TYPE "Priority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EMPLOYEE',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"tokenHash" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Asset" ("id" TEXT PRIMARY KEY,"assetTag" TEXT NOT NULL,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"serialNumber" TEXT NOT NULL,"status" "AssetStatus" NOT NULL DEFAULT 'AVAILABLE',"location" TEXT NOT NULL,"assigneeId" TEXT,"purchasedAt" TIMESTAMP(3),"warrantyEndsAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Asset_assetTag_key" ON "Asset"("assetTag"); CREATE UNIQUE INDEX "Asset_serialNumber_key" ON "Asset"("serialNumber"); CREATE INDEX "Asset_assigneeId_idx" ON "Asset"("assigneeId"); CREATE INDEX "Asset_status_idx" ON "Asset"("status");
CREATE TABLE "Ticket" ("id" TEXT PRIMARY KEY,"number" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "TicketStatus" NOT NULL DEFAULT 'OPEN',"priority" "Priority" NOT NULL DEFAULT 'MEDIUM',"reporterId" TEXT NOT NULL,"assigneeId" TEXT,"assetId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Ticket_number_key" ON "Ticket"("number"); CREATE INDEX "Ticket_reporterId_idx" ON "Ticket"("reporterId"); CREATE INDEX "Ticket_assigneeId_idx" ON "Ticket"("assigneeId"); CREATE INDEX "Ticket_assetId_idx" ON "Ticket"("assetId"); CREATE INDEX "Ticket_status_priority_idx" ON "Ticket"("status","priority");
CREATE TABLE "TicketComment" ("id" TEXT PRIMARY KEY,"ticketId" TEXT NOT NULL,"authorId" TEXT NOT NULL,"body" TEXT NOT NULL,"internal" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "TicketComment_ticketId_idx" ON "TicketComment"("ticketId");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Asset" ADD CONSTRAINT "Asset_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_assigneeId_fkey" FOREIGN KEY ("assigneeId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Ticket" ADD CONSTRAINT "Ticket_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "TicketComment" ADD CONSTRAINT "TicketComment_ticketId_fkey" FOREIGN KEY ("ticketId") REFERENCES "Ticket"("id") ON DELETE CASCADE ON UPDATE CASCADE;
